import{z as d,x as A,o as t,c as p,q as i,j as s,D as r,d as l,s as o,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Schedule-Free 优化","description":"","frontmatter":{"title":"Schedule-Free 优化","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/schedule-free-optimizer.md","filePath":"llm/schedule-free-optimizer.md","lastUpdated":1791413859000}'),B={name:"llm/schedule-free-optimizer.md"};function m(c,e,h,u,f,D){const E=A("Mermaid");return t(),p("div",null,[e[2]||(e[2]=i('<h1 id="schedule-free-优化" tabindex="-1">Schedule-Free 优化 <a class="header-anchor" href="#schedule-free-优化" aria-label="Permalink to &quot;Schedule-Free 优化&quot;">​</a></h1><div class="epigraph"><p>学习率调度的活儿交给优化器自己：平均点做评估、迭代点做探索，训练中途随时停、随时最优——日程表进了优化器内部。</p><footer>—— 据 Defazio et al.「The Road Less Scheduled」(2024)；Primal Averaging 与 Polyak–Ruppert 平均</footer></div><p><a href="/llm/wsd-schedule">WSD 调度</a>把退火长度压到 10%，但仍要人工选退火点。缺口是<strong>Schedule-Free 优化器</strong>：把「探索序列」与「收敛序列」拆成两个点的轨迹，评估用平均点、更新用插值点，学习率可以恒定不退——调度被内化成优化器的两点结构。本课不进加速理论的严格证明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典真理：Polyak–Ruppert 平均对凸问题免费提收敛率，但平均点更新不了参数（平均点不是迭代点）。AdamW 一步到位、单点轨迹，于是必须用外挂调度把「探索」与「收敛」压进同一条线。缺口：能不能让迭代点保持 AdamW 的探索力、同时平均点保有退火后的收敛性——两个点各干各的。</p><p><span class="marginnote">术语翻译：Schedule-Free = Defazio et al. 2024 提出的优化器族，核心是 primal averaging 的变体：维护迭代序列 \\(z\\)（探索）与平均序列 \\(x\\)（评估），每步以动量权重 γ 在两点间插值；评估永远用 \\(x\\)，checkpoint 只存 \\(x, z, y\\) 三组参数。</span></p><p><span class="marginnote">数字实例：同 10T token 预算，AdamW+cosine 需在开训前定 \\(T\\)；Schedule-Free 全程恒定 \\(\\eta\\)，训练 5T 时停下评估——平均点已处「相当于退火完」的状态；想继续就接着跑，无需改任何超参。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>迭代三行代码：\\(y_t=(1-\\gamma)z_t+\\gamma x_t\\)（插值点，进梯度计算）；\\(z_{t+1}=z_t-\\eta\\nabla f(y_t)\\)（探索点，纯 SGD 步）；\\(x_{t+1}=(1-\\frac1{t+1})x_t+\\frac1{t+1}z_{t+1}\\)（平均点，评估用）。工程上与 AdamW 的加权版本组合（把 SGD 步换成 Adam 更新），momentum 参数由 γ 承担。超参面只剩 \\(\\eta\\) 与 γ（常用 0.9）——调度超参整族消失。</p>',9)),(t(),s(n,null,{default:r(()=>[o(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8F%92%E5%80%BC%E7%82%B9%20y%20%3D%20(1-%CE%B3)z%20%2B%20%CE%B3x%22%5D%20--%3E%20B%5B%22%E5%9C%A8%20y%20%E7%AE%97%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20B%20--%3E%20C%5B%22z%20%3D%20z%20-%20%CE%B7%E2%88%87f(y)%20%20%E6%8E%A2%E7%B4%A2%22%5D%0A%20%20C%20--%3E%20D%5B%22x%20%3D%20%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%20z%20%20%E8%AF%84%E4%BC%B0%22%5D%0A%20%20D%20--%3E%20A%0A%20%20E%7B%22%E4%BD%95%E6%97%B6%E5%81%9C%3F%22%7D%20--%3E%7C%22%E9%9A%8F%E6%97%B6%22%7C%20F%5B%22x%20%E5%B7%B2%E6%98%AF%E6%94%B6%E6%95%9B%E7%82%B9%22%5D%0A%20%20F%20--%3E%20A%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：像探险队兵分两路——\\(z\\) 是先锋（永远大步探路，不怕回头的代价），\\(x\\) 是按所有足迹重心的「决策参谋」（位置平滑、随时可汇报）。调度型优化器只有一支队伍，探索时汇报不了、汇报时探不了路。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,[l("收敛机制来自"),a("strong",null,"在线学习与凸优化的等价性"),l("：primal averaging 在凸光滑情形自动获得与「最好调度」匹配的收敛率——不是「调度效果差」，而是「平均轨迹把调度的效果免费实现」。与 WSD 的噪声视角对照：WSD 靠降 η 压梯度噪声，Schedule-Free 靠平均压参数噪声——两个噪声源各治其一，故实践中两者还可叠加（Schedule-Free + 平台末退火）再赚一点。LLM 训练的实证：MLP/Transformer 语言模型上与 cosine 持平或略优，且「中途最优」是 cosine 永远给不了的。")],-1)),(t(),s(n,null,{default:r(()=>[o(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%B0%81%E5%9C%A8%E5%8E%8B%E5%99%AA%E5%A3%B0%3F%22%7D%20--%3E%7C%22WSD%3A%20%E9%99%8D%20%CE%B7%22%7C%20R%5B%22%E6%A2%AF%E5%BA%A6%E5%99%AA%E5%A3%B0%20%E2%86%93%22%5D%0A%20%20Q%20--%3E%7C%22SF%3A%20%E5%B9%B3%E5%9D%87%22%7C%20S%5B%22%E5%8F%82%E6%95%B0%E5%99%AA%E5%A3%B0%20%E2%86%93%22%5D%0A%20%20R%20--%3E%20T%5B%22%E5%8F%AF%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20S%20--%3E%20T%0A%20%20U%7B%22%E5%87%B8%E7%90%86%E8%AE%BA%E8%AF%B4%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%20V%5B%22primal%20averaging%20%E8%87%AA%E5%8A%A8%E5%8C%B9%E9%85%8D%E6%9C%80%E4%BC%98%E8%B0%83%E5%BA%A6%E7%8E%87%22%5D%0A%20%20V%20--%3E%20W%5B%22%E8%B0%83%E5%BA%A6%E6%95%88%E6%9E%9C%E8%A2%AB%E5%86%85%E5%8C%96%22%5D%0A%20%20W%20--%3E%20T%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p><span class="marginnote">常见误区：拿 \\(z\\)（迭代点）去评测——迭代点带探索噪声，永远比 \\(x\\) 差；另一误区是照搬 AdamW 的 β₁/β₂——Schedule-Free 的动量由 γ 承担，β₁ 常设 0.9 会出现双重动量，官方推荐 β₁=0.9 配 γ=0.9 或直接 β₁=0。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本：每步多存两组参数（显存 +2 倍参数量），7B 模型按 fp32 计多 56 GB——用 ZeRO 分片摊薄，但推理侧无碍（部署 \\(x\\)）。非凸理论仍不完整，Transformer 上的实证优势在 0–2% 区间浮动，胜负取决于调参投入——cosine 生态成熟是它的真实护城河。与微调的适配：小步数下平均点尚「没攒够」，短程微调仍建议经典调度。与 <a href="/llm/qk-clip">QK-Clip</a> 的分工：那是在注意力内部做稳定性手术，本课是全局节奏的重构——一层细节一层骨架，互不替代。</p><p><span class="marginnote">直觉类比：传统调度像做一桌菜必须按菜谱从头炖到尾，中途端上桌是半生不熟；Schedule-Free 像火锅——锅里的「平均态」随时可以夹出来吃，想继续煮就继续煮，火候由锅（优化器）自己管。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两点结构：迭代点 \\(z\\) 探索、平均点 \\(x\\) 评估，调度内化为动量插值。</li><li>超参面缩小到 η 与 γ；中途任意点停都是收敛态。</li><li>显存 +2 参数组是真成本；短程任务收益有限。</li><li>出处：Defazio et al.「The Road Less Scheduled」2024；Polyak–Ruppert 平均；Meta 开源实现。</li></ul>',6))])}const C=d(B,[["render",m]]);export{S as __pageData,C as default};
